from pathlib import Path
import json,hashlib,zipfile,subprocess,sys
D=Path(__file__).resolve().parents[2];B=D/'stage7-bengkayang';R=D.parent;H=D/'blokraya-stage7-bengkayang.html'
subprocess.run([sys.executable,str(B/'source/report.py')],check=True)
read=lambda n:json.loads((B/(n+'.json')).read_text());reports={n:read(n)for n in ['physics-tests','item-tests','surface-tests','world-tests','browser-tests','offline-tests','unchanged-renders','scope-tests','comparison-report','release-smoke']}
for n,r in reports.items():assert r['status']=='passed',n
raw=H.read_bytes();sha=lambda x:hashlib.sha256(x).hexdigest();metrics=read('asset-metrics');assert sha(raw)==metrics['html_sha256'];assert reports['release-smoke']['html_sha256']==sha(raw);assert raw==Path('/tmp/blokraya-6d/candidate.html').read_bytes()
metrics.update({'under_25_decimal_MB':len(raw)<25000000,'reports':{n:len(r.get('checks',[]))for n,r in reports.items()},'teacher_export_bytes':reports['offline-tests']['export_bytes'],'offline_asset_HTTP_requests':len(reports['offline-tests']['assetRequests']),'direct_file_note':read('direct-file-tests').get('reason'),'release_status':'Ready for visual review; reference accuracy and direct file navigation have documented limitations.'})
notes='BLOKRAYA — STAGE 7 BENGKAYANG: WATERFALL ADVENTURE (6D)\n\nEkstrak ZIP lalu buka blokraya-stage7-bengkayang.html pada browser modern dengan WebGL. Seluruh aset tertanam. Data lama dibaca pada browser/profil/origin yang sama. Mode Siswa tanpa PIN; Mode Guru memakai PIN lokal. Klik/sentuh untuk audio.\n\nTujuh arena playable: Pontianak, Mempawah, Singkawang, Sambas, Sintang, Kapuas Hulu dan Bengkayang. Yogyakarta, Bali dan Bromo tetap Segera Hadir. Kalbar Klasik tetap tiga arena awal; Nusantara menunggu tiga world terakhir. Tidak memberikan token atau unlock QA pada distribusi.\n\nJalur wisata fiktif 801,04 m dengan air terjun lebar terinspirasi Riam Merasap, kolam, sungai berbatu, dua jembatan, dek pandang, hutan hujan dan perbukitan. Bukan peta atau rekonstruksi geografis/ekologis. Akses referensi web ditolak HTTP 403. Ukuran dan tata lingkungan merupakan desain game, bukan ukuran/denah landmark asli.\n\nPengujian offline lulus dengan jaringan browser dimatikan dan dokumen lokal disuplai harness pada localhost, tanpa permintaan HTTP/CDN aset. Navigasi langsung file:// dicoba tetapi diblokir administrator browser cloud. Membuka langsung pada browser target dan HP fisik/FPS/memori belum terverifikasi; tidak menambahkan server wajib atau loader fetch aset lokal.\n\nKontrol A/D/panah, W/S gas/rem, C drift, Shift jump, E/Spasi buff, Q/1/2 slot, P/Esc jeda, serta kontrol sentuh. Soal menjeda simulasi. Nilai akademik tetap terpisah dari hasil balapan.\n\nZIP review berisi sumber builder JavaScript prosedural/track/metadata, screenshot renderer asli, thumbnail, metrik dan laporan. Build memerlukan checkout baseline Kapuas Hulu; lihat README. Blender tidak diperlukan untuk builder prosedural ini.\n\nTidak merge ke main, mengubah index.html, deployment atau mengerjakan 6E.\n'
for kind in ['playable','review']:
 dest=R/f'blokraya-stage7-bengkayang-{kind}.zip'
 with zipfile.ZipFile(dest,'w',zipfile.ZIP_DEFLATED,compresslevel=9)as z:
  z.write(H,H.name);z.writestr('MULAI.txt',notes)
  if kind=='review':
   for f in sorted(B.rglob('*')):
    if f.is_file()and '__pycache__'not in f.parts and f.name!='release-metrics.json':z.write(f,'stage7-bengkayang/'+f.relative_to(B).as_posix())
   z.writestr('stage7-bengkayang/release-metrics.json',json.dumps({**metrics,'review_self_hash_omitted':True,'review_self_hash_note':'The full review ZIP hash lives in the repository release-metrics.json; an archive cannot contain its own final hash.'},indent=2))
 with zipfile.ZipFile(dest)as z:assert z.testzip()is None;assert z.read(H.name)==raw;entries=len(z.namelist())
 metrics[kind+'_zip']={'file':dest.name,'bytes':dest.stat().st_size,'sha256':sha(dest.read_bytes()),'crc_ok':True,'html_identical':True,'entries':entries}
(B/'release-metrics.json').write_text(json.dumps(metrics,indent=2));print(json.dumps({k:metrics[k]for k in ['html_bytes','growth_bytes','html_sha256','playable_zip','review_zip']},indent=2))
